INSERT INTO `courses` (`id`, `action_user`, `course_industries_id`, `qualification_id`, `course_categories_id`, `course_code`, `course_name`, `course_desc`, `rto`, `thumbnail`, `checklist`, `isPublished`, `created_at`, `updated_at`) VALUES
(3, 1, 6, 1, 22, 'CPC10111', 'Certificate I in Construction', '<h2 style=\"text-align: justify;\">What\'s it all about?</h2>\r\n<p style=\"text-align: justify;\">This qualification provides basic construction skills and is an introduction to the construction industry, its culture, occupations, job roles and workplace expectations. The units of competency cover essential work health and safety requirements, the industrial and work organisation structure, communication skills, work planning, and basic use of tools and materials. The qualification is built around a basic construction project unit that integrates the skills and embeds the facets of employability skills in context.<br /><br />On successful completion you will be issued with the nationally recognised qualification: CPC10111 Certificate I in Construction.<br /><br />This training has been grouped into a series of short courses, which provide a progressive and practical learning experience. The short courses are:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>Basic Workplace Skills</li>\r\n<li>Construction Project</li>\r\n<li>Using Construction Tools &ndash; Basics</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">More detailed information on the content and format of this qualification can be found in the &lsquo;Nationally Recognised training details&rsquo; section of this page.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h2 style=\"text-align: justify;\">Who would do this training?</h2>\r\n<p style=\"text-align: justify;\">This course is suitable for:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>School leaver&rsquo;s wishing to undertake pre-vocational training to provide some skills in general construction prior to choosing a trade or para-professional career path.</li>\r\n<li>Workers or job seekers wishing to gain basic skills in the construction industry</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h2 style=\"text-align: justify;\">What do I need before I start?</h2>\r\n<p style=\"text-align: justify;\">Itec will conduct a pre-enrolment review with you to make sure that this program is suitable for your needs, current skills and experience.<br /><br />To start this program, you must have:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>A good understanding of English reading and writing and numeracy</li>\r\n<li>Suitable interpersonal and communication skills</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">The program will take 120 hours to complete. This may be delivered in 3 x 40 hour blocks or spread out over 15 weeks (8 hours per week).</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h2 style=\"text-align: justify;\">Required resources</h2>\r\n<p style=\"text-align: justify;\">Participants are required to have a copy of the Pearson&rsquo;s Basic Building and Construction Skill Participant Guide.</p>', 'Alpha College', '1.jpg', 'CPC10111 - Certificate I in Construction.pdf', 1, '2021-04-26 01:02:26', '2021-06-01 04:46:34'),
(4, 1, 7, 1, 23, 'BSB20215', 'Certificate II in Customer Engagement', '<h2>Qualification Description</h2>\r\n<p>This qualification reflects the role of individuals who typically work with multiple communication channels, capture data and provide customer service. Typically, individuals in this role work under direct supervision, with limited authority to delegate.</p>\r\n<p>Licensing/Regulatory Information&nbsp;</p>\r\n<p>No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>Nil</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 9&nbsp;</p>\r\n<p>3 core units&nbsp;&nbsp;plus</p>\r\n<p>6 elective units&nbsp;, of which:</p>\r\n<ul>\r\n<li>3 units must be from the elective units below</li>\r\n<li>the remaining 3 units may be from the elective units below, or from qualifications at the same level or one higher in any endorsed Training Package or accredited course.</li>\r\n</ul>\r\n<p>Elective units must be relevant to the work environment and the qualification, maintain the integrity of the AQF alignment and contribute to a valid, industry-supported vocational outcome.</p>\r\n<p>&nbsp;</p>\r\n<h2>Core Units&nbsp;</h2>\r\n<p>BSBCUE203 Conduct customer engagement</p>\r\n<p>BSBCUE205 Prepare for work in a customer engagement environment</p>\r\n<p>BSBCMM201 Communicate in the workplace</p>\r\n<p>&nbsp;</p>\r\n<h2>Elective Units&nbsp;</h2>\r\n<p>BSBCUE301 Use multiple information systems</p>\r\n<p>BSBCUE305 Process credit applications</p>\r\n<p>BSBCUE308 Conduct outbound customer engagement</p>\r\n<p>BSBCUE309 Develop product and service knowledge for customer engagement operation</p>\r\n<p>BSBCMM301 Process customer complaints</p>\r\n<p>BSBCUS201 Deliver a service to customers</p>\r\n<p>BSBITU111 Operate a personal digital device</p>\r\n<p>BSBITU213 Use digital technologies to communicate remotely</p>\r\n<p>BSBLED301 Undertake e-learning</p>\r\n<p>BSBWHS201 Contribute to health and safety of self and others</p>\r\n<p>BSBWOR201 Manage personal stress in the workplace</p>\r\n<p>BSBWOR203 Work effectively with others</p>\r\n<p>ICTICT103 Use, communicate and search securely on the internet</p>\r\n<p>ICTICT203 Operate application software packages</p>', NULL, '55.jpg', 'BSB20215 - Certificate II in Customer Engagement.pdf', 1, '2021-04-26 01:05:08', '2021-06-01 05:38:44'),
(5, 1, 6, 1, 23, 'CPC20112', 'Certificate II in Construction', '<h2>Description</h2>\r\n<p>This qualification provides a pathway to the primary trades in the construction industry with the exception of plumbing. Trade outcomes are predominantly achieved through an Australian Apprenticeship and this Certificate II allows for inclusion of skills suited for entry to off-site occupations, such as joinery and shopfitting as well as carpentry, bricklaying and other occupations in general construction.</p>\r\n<p>This Certificate II is designed to introduce learners to the recognised trade callings in the construction industry and provide meaningful credit in a construction industry Australian Apprenticeship.</p>\r\n<p>The qualification has core unit of competency requirements that are required in most Certificate III qualifications. The elective options are structured to allow choice from areas of trade skills as an introduction to a range of occupations.</p>\r\n<p>The construction industry strongly affirms that training and assessment leading to recognition of skills must be undertaken in a real or very closely simulated workplace environment and this qualification requires all units of competency to be delivered in this context.</p>\r\n<p>Completion of the general induction training program specified by the National Code of Practice for Induction Training for Construction Work (ASCC 2007) is required before entering a construction work site. Achievement of unit CPCCOHS1001A covers this requirement.</p>\r\n<p>&nbsp;</p>\r\n<h2>Pathways Information</h2>\r\n<p>Not Applicable</p>\r\n<h2>Licensing/Regulatory Information</h2>\r\n<p>Not applicable.</p>\r\n<p>&nbsp;</p>\r\n<h2>Entry Requirements</h2>\r\n<p>Not Applicable</p>\r\n<h2>Employability Skills Summary</h2>\r\n<p>&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"208\">\r\n<p>Employability skill&nbsp;</p>\r\n</td>\r\n<td width=\"737\">\r\n<p>Industry/enterprise requirements for this qualification include:&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>Communication&nbsp;</p>\r\n</td>\r\n<td width=\"737\">\r\n<ul>\r\n<li>Communicates with clients, colleagues and others using effective and appropriate communication techniques, including:</li>\r\n</ul>\r\n<ul>\r\n<li>Clear and direct communication</li>\r\n<li>Active listening</li>\r\n<li>Verbal and non-verbal language</li>\r\n<li>Questioning to identify and confirm requirements</li>\r\n<li>Language and concepts appropriate to cultural differences</li>\r\n</ul>\r\n<ul>\r\n<li>Follows instructions from supervisor and other relevant persons</li>\r\n<li>Understands, interprets and applies information as required from:</li>\r\n</ul>\r\n<ul>\r\n<li>Environmental and work health and safety (WHS) requirements, including safety data sheets (SDS)</li>\r\n<li>Plans, drawings and specifications</li>\r\n<li>Schedules</li>\r\n<li>Industry-specific resources, such as Moh\'s scale</li>\r\n<li>Load tables</li>\r\n<li>Safety signs and symbols</li>\r\n<li>Organisational policies and procedures</li>\r\n</ul>\r\n<ul>\r\n<li>Understands relevant definitions, terminology, symbols, abbreviations and language</li>\r\n<li>Records relevant information using standard workplace documentation</li>\r\n<li>Applies measurements and calculations using appropriate equipment, formulas and records as required</li>\r\n<li>Reports and records hazards and risks</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>Teamwork&nbsp;</p>\r\n</td>\r\n<td width=\"737\">\r\n<ul>\r\n<li>Works as part of a team</li>\r\n<li>Provides assistance and encouragement to other team members</li>\r\n<li>Initiates and encourages improvements in team performance</li>\r\n<li>Identifies and uses the strengths of other team members</li>\r\n<li>Relates to people from diverse social, cultural and ethnic backgrounds and with varying physical and mental abilities</li>\r\n<li>Participates in on-site meetings</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>Problem solving&nbsp;</p>\r\n</td>\r\n<td width=\"737\">\r\n<ul>\r\n<li>Examines tools and equipment prior to use for damage, missing components or other defects</li>\r\n<li>Identifies typical faults and problems and takes remedial action and/or reports to supervisor</li>\r\n<li>Rectifies simple faults with tools and equipment</li>\r\n<li>Identifies methods of prevention and control for water penetration</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>Initiative and enterprise&nbsp;</p>\r\n</td>\r\n<td width=\"737\">\r\n<ul>\r\n<li>Identifies opportunities to improve resource efficiency and makes suggestions as appropriate</li>\r\n<li>Responds to change and workplace challenges</li>\r\n<li>Puts ideas into action</li>\r\n<li>Maximises use of resources by recycling, re-using or using appropriate disposal methods</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>Planning and organising&nbsp;</p>\r\n</td>\r\n<td width=\"737\">\r\n<ul>\r\n<li>Identifies hazards and implements appropriate hazard control measures</li>\r\n<li>Selects and uses appropriate materials, tools and equipment</li>\r\n<li>Determines material quantity requirements and checks for conformity to requirements</li>\r\n<li>Prioritises and sequences tasks</li>\r\n<li>Applies time management skills to ensure work is completed to time requirements</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>Self management&nbsp;</p>\r\n</td>\r\n<td width=\"737\">\r\n<ul>\r\n<li>Evaluates own actions and makes judgements about performance and necessary improvements</li>\r\n<li>Contributes to workplace responsibilities, such as current work site environmental/sustainability frameworks or management systems</li>\r\n<li>Manages own performance to meet workplace standards</li>\r\n<li>Seeks support to improve work performance</li>\r\n<li>Cleans up work area, including tools and equipment</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>Learning&nbsp;</p>\r\n</td>\r\n<td width=\"737\">\r\n<ul>\r\n<li>Identifies own learning needs and seeks skill development as required</li>\r\n<li>Is open to learning new ideas and techniques</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\">\r\n<p>Technology&nbsp;</p>\r\n</td>\r\n<td width=\"737\">\r\n<ul>\r\n<li>Uses calculators</li>\r\n<li>Uses and operates a range of tools and equipment correctly and safely</li>\r\n<li>Properly starts up, operates and shuts down equipment</li>\r\n<li>Carries out pre- and post-operational checks on equipment and machines</li>\r\n<li>Performs tool and equipment maintenance as required</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<h2>Packaging Rules</h2>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>To achieve this qualification, the candidate must demonstrate competency in:</p>\r\n<p>12 units of competency:</p>\r\n<ul>\r\n<li>6 core units</li>\r\n<li>6 elective units.</li>\r\n</ul>\r\n<p>The elective units are to be chosen as follows:</p>\r\n<ul>\r\n<li>no less than 4 units and up to 6 units from Groups A to G, with no less than 2 units from any individual group</li>\r\n<li>up to 2 units from Group H</li>\r\n<li>1 unit may be chosen from Certificate I or II qualifications in CPC08 or another current Training Package or accredited course, provided the integrity of the AQF alignment is ensured, and they contribute to a valid, industry-supported vocational outcome.</li>\r\n</ul>\r\n<p>The wide range of electives is drawn from Certificate III units of competency in CPC08 Construction, Plumbing and Services Training Package. Units of competency from Plumbing and Services qualifications are not available, as there are different plumbing and services pathways to Certificate III outcomes.</p>\r\n<p>Some units in this qualification may have prerequisite requirements, which must be met when packaging the qualification. Users are referred to the list of CPC08 units with prerequisite unit requirements available in this Training Package for this purpose.</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Core units&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCCM1012A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Work effectively and sustainably in the construction industry</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCCM1013A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Plan and organise work</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCCM1014A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Conduct workplace communication</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCCM1015A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Carry out measurements and calculations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCCM2001A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Read and interpret plans and specifications</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCOHS2001A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Apply OHS requirements, policies and procedures in the construction industry</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Elective units&nbsp;&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Group A: Brick and blocklaying&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" valign=\"middle\" width=\"943\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCBL2001A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Handle and prepare bricklaying and blocklaying materials</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCBL2002A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Use bricklaying and blocklaying tools and equipment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Group B: Carpentry&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" valign=\"middle\" width=\"943\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCCA2002B</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Use carpentry tools and equipment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCCA2003A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Erect and dismantle formwork for footings and slabs on ground</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCCA2011A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Handle carpentry materials</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Group C: Solid plastering&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" valign=\"middle\" width=\"943\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCSP2001A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Handle solid plastering materials</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCSP2002A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Use solid plastering tools and equipment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCSP2003A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Prepare surfaces for plastering</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Group D: Wall and floor tiling&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" valign=\"middle\" width=\"943\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCWF2001A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Handle wall and floor tiling materials</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCWF2002A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Use wall and floor tiling tools and equipment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCWF3001A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Prepare surfaces for tiling application</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Group E: Waterproofing&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCWP2001A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Handle waterproofing materials</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCWP2002A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Use waterproofing tools and equipment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCWP2003A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Prepare for construction waterproofing process</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCWP2004A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Prepare surfaces for waterproofing application</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Group F: Joinery and shopfitting&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCJN2001A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Assemble components</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCJN2002B</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Prepare for off-site manufacturing process</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCSH2001A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Prepare surfaces</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Group G: Stonemasonry&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCST2001A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Prepare for stonemasonry construction process</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCST2003A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Finish stone</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCST2006A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Identify and use stone products</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"237\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td width=\"747\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Group H: General elective units&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCCM2004A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Handle construction materials</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCCM2006B</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Apply basic levelling procedures</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCCM2009A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Carry out basic demolition</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCCM2010B</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Work safely at heights</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCCO2013A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Carry out concreting to simple forms</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>CPCCJN3001A</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Use static machines</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>RIICCM210D</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Install trench support</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>RIIWHS205D</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Control traffic with stop-slow bat</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\" width=\"237\">\r\n<p>RIIWMG203D</p>\r\n</td>\r\n<td valign=\"middle\" width=\"747\">\r\n<p>Drain and dewater civil construction site</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', NULL, '2.jpg', 'CPC20112 - Certificate II in Construction.pdf', 1, '2021-04-26 01:07:55', '2021-06-02 03:17:13'),
(6, 1, 6, 1, 23, 'RII20715', 'Certificate II in Civil Construction', '<h2>Qualification Description</h2>\r\n<p>This qualification reflects the role of individuals working in an operational role in civil construction, who undertake a prescribed range of tasks using limited practical skills and fundamental knowledge, in a defined context working under supervision.</p>\r\n<p>Licensing, legislative, regulatory and certification requirements that apply to this qualification can vary between states, territories, and industry sectors. Relevant information must be sourced prior to application of the qualification.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>There are no entry requirements for this qualification.</p>\r\n<h2>Packaging Rules</h2>\r\n<p>The following provides the packaging rules for this qualification, followed by the list of relevant units of competency.</p>\r\n<p>Total number of units = 16&nbsp;</p>\r\n<p>10 core units&nbsp; plus</p>\r\n<p>6 elective units,&nbsp;&nbsp;of which:</p>\r\n<ul>\r\n<li>at least five (5) must be chosen from electives</li>\r\n<li>no more than one (1) may be chosen from elsewhere within this training package, or from another endorsed training package, or from an accredited course.</li>\r\n</ul>\r\n<p>All elective units selected from outside this qualification must reflect current occupational and learning outcomes of this AQF qualification level.</p>\r\n<p>There are both licensed and non-licensed units of competency relating to high risk work in the Resources and Infrastructure Industry Training Package. To be appointed under any statutory requirements in related roles, units of competency should be selected to meet the state/territory licensing requirements.</p>\r\n<p>There are prerequisites to imported units listed in this qualification. Where a unit is imported as an elective care must be taken to ensure that all prerequisites specified are complied with.</p>\r\n<p>&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Core units of competency</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>Unit code&nbsp;</p>\r\n</td>\r\n<td width=\"742\">\r\n<p>Unit title&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIIBEF201D</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Plan and organise work</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>RIICCM201D</p>\r\n</td>\r\n<td width=\"742\">\r\n<p>Carry out measurements and calculations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>RIICCM202D</p>\r\n</td>\r\n<td width=\"742\">\r\n<p>Identify, locate and protect underground services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>RIICCM203D</p>\r\n</td>\r\n<td width=\"742\">\r\n<p>Read and interpret plans and job specifications</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>RIICCM205E</p>\r\n</td>\r\n<td width=\"742\">\r\n<p>Carry out manual excavation</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>RIICCM207D</p>\r\n</td>\r\n<td width=\"742\">\r\n<p>Spread and compact materials manually</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>RIICOM201D</p>\r\n</td>\r\n<td width=\"742\">\r\n<p>Communicate in the workplace</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>RIISAM203D</p>\r\n</td>\r\n<td width=\"742\">\r\n<p>Use hand and power tools</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>RIISAM204D</p>\r\n</td>\r\n<td width=\"742\">\r\n<p>Operate small plant and equipment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>RIIWHS201D</p>\r\n</td>\r\n<td width=\"742\">\r\n<p>Work safely and follow WHS policies and procedures</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<h4>Electives</h4>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>Unit code&nbsp;</p>\r\n</td>\r\n<td width=\"742\">\r\n<p>Unit title&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>BSBDIV301</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Work effectively with diversity</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>CPCCCM2007B</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Use explosive power tools</p>\r\n<p>&bull; Prerequisite unit: CPCCOHS2001A Apply OHS requirements, policies and procedures in the construction industry</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>CPCCLDG3001A</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Licence to perform dogging</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>CPCCLRG3001A</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Licence to perform rigging basic level</p>\r\n<p>&bull; Prerequisite unit: CPCCLDG3001A Licence to perform dogging</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>CPCCLSF2001A</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Licence to erect, alter and dismantle scaffolding basic level</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>FWPCOT2239</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Trim and cross cut felled trees</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>FWPFGM3212</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Fall trees manually (intermediate)</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIICBS202D</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Hand spread asphalt</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIICCM206D</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Support plant operations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIICCM208D</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Carry out basic levelling</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIICCM209D</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Carry out concrete work</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIICCM210D</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Install trench support</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIICCM211D</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Erect and dismantle temporary fencing and gates</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIICFW306D</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Direct pile driving operations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIICFW307D</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Direct cast in-situ piling operations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIICRC201D</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Repair potholes</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIICRC208D</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Lay pipes</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIIHAN211D</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Conduct basic scaffolding operations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIIHAN301E</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Operate elevating work platform</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIIRIS202D</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Respond to site based spills</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>RIISAM201D</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Handle resources and infrastructure materials and safely dispose of nontoxic materials</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIISAM205D</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Cut, weld and bend materials</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIIVEH304E</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Conduct tip truck operations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIIWHS202D</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Enter and work in confined spaces</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIIWHS205D</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Control traffic with stop-slow bat</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"bottom\" width=\"207\">\r\n<p>RIIWMG203D</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Drain and dewater civil construction site</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"207\">\r\n<p>TLILIC0005</p>\r\n</td>\r\n<td valign=\"bottom\" width=\"742\">\r\n<p>Licence to operate a boom-type elevating work platform (boom length 11 metres or more)</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', NULL, '3.jpg', 'RII20715- Certificate II in Civil Construction.pdf', 1, '2021-04-26 01:08:43', '2021-06-02 03:50:06'),
(7, 1, 7, 1, 23, 'SIR20216', 'Certificate II in Retail Services', '<div id=\"lipsum\">\r\n<h2>Qualification Description</h2>\r\n<p>This qualification reflects the role of frontline retail team members who use a defined and limited range of operational skills to undertake workplace activities. They are involved in mainly routine and repetitive tasks and work under direct supervision of others.</p>\r\n<p>&nbsp;</p>\r\n<p>This qualification provides a pathway to work in a diverse range of retail settings including specialty retailers, supermarkets, department stores and quick service restaurants.</p>\r\n<p>&nbsp;</p>\r\n<p>Individuals with this qualification are able to perform roles such as frontline team member, customer service assistant and point-of-sale operator.</p>\r\n<p>&nbsp;</p>\r\n<p>No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>There are no entry requirements for this qualification.</p>\r\n<h2>Packaging Rules</h2>\r\n<p>12 units must be completed:</p>\r\n<ul>\r\n<li>7 core units</li>\r\n<li>5 elective units, consisting of:</li>\r\n</ul>\r\n<ul>\r\n<li>3 units from the list below</li>\r\n<li>2 units from the list below, elsewhere in SIR Retail Services Training Package, or any other current Training Package or accredited course.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>The selection of electives must be guided by the job outcome sought, local industry requirements and the complexity of skills appropriate to the AQF level of this qualification.</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Core units&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>SIRXCEG001</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Engage the customer</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>SIRXCOM001</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Communicate in the workplace to support team and customer outcomes</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>SIRXIND001</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Work effectively in a service environment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>SIRXIND003</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Organise personal work requirements</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>SIRXPDK001</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Advise on products and services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>SIRXRSK001</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Identify and respond to security risks</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>SIRXWHS002</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Contribute to workplace health and safety</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Elective units&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Food Safety&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>SIRRFSA001</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Handle food safely in a retail environment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Inventory&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>SIRRINV001</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Receive and handle retail stock</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Merchandising&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>SIRRMER001</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Produce visual merchandise displays</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>SIRRMER002</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Merchandise food products</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Online and Social Media&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>SIRXOSM001</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Identify and review social media and online platforms for organisational use</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Product Knowledge&nbsp;&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>SIRXPDK002</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Advise on food products and services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Sales&nbsp;&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>SIRXSLS002</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Follow point-of-sale procedures</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Technology&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>BSBWOR204</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Use business technology</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Working in Industry&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>FSKLRG09</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Use strategies to respond to routine workplace problems</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>SIRXIND002</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Organise and maintain the store environment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>SIRXIND004</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Plan a career in the retail industry</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"514\">\r\n<p>SIRXCEG008</p>\r\n</td>\r\n<td width=\"943\">\r\n<p>Manage disrespectful, aggressive or abusive customers</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>', NULL, '56.jpg', 'SIR20216-Certificate II in Retail Services.pdf', 1, '2021-04-26 01:09:31', '2021-06-02 02:40:20'),
(8, 1, 6, 1, 24, 'AHC30916', 'Certificate III in Landscape Construction', '<h2>Course overview</h2>\r\n<div>\r\n<p>Get a head start on your landscaping career with this entry-level course.&nbsp;This course will give you the skills to construct landscaping projects and renew and maintain existing gardens.</p>\r\n<p>According to the Australian Government\'s Job Outlook service, the number of people working as landscape gardeners grew strongly over the past five years. The industry is expected to see strong future growth, ensuring your skills will be in high demand when you graduate.&nbsp;</p>\r\n<p>You\'ll develop the knowledge and skills required to&nbsp;install drainage, construct brick, block and concrete structures, provide information on plants, and cost out projects. Our highly experienced staff are still strongly embedded in the industry and will give you the one-on-one guidance you need to succeed.</p>\r\n<p>Successful completion of this course will qualify you to work as a landscape gardener, greenskeeper, or parks and gardens tradesperson.</p>\r\n</div>', 'Alpha College', '4.jpg', 'AHC30916-Certificate III in Landscape Construction.pdf', 1, '2021-04-26 01:14:56', '2021-06-01 05:12:24'),
(9, 1, 8, 1, 24, 'AMP30516', 'Certificate III in Meat Processing (Slaughtering)', '<div id=\"lipsum\">\r\n<p style=\"text-align: justify;\">AMP30516&nbsp;Certificate III in Meat Processing (Slaughtering) is the specific qualification for individuals involved in the slaughtering and dressing of animals in an abattoir.</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>Available as a traineeship &ndash;&nbsp;YES</li>\r\n<li>Total number of units required &ndash; twelve (12) units</li>\r\n<li>Course duration &ndash; 12 to 18 months</li>\r\n<li>Non traineeship funding available &ndash; NO</li>\r\n<li>Price range &ndash; $1400 to $4100&nbsp;(Student tuition fees are indicative only and are subject to change given individual circumstances at enrolement. &nbsp;Additional fees may apply such as student services and resource fees)</li>\r\n</ul>\r\n<h4 style=\"text-align: justify;\">COURSE OUTLINE:</h4>\r\n<p style=\"text-align: justify;\">Certificate III in Meat Processing (Slaughtering) &nbsp;is a qualification suitable for those with a job role in slaughtering and dressing within an abattoir. &nbsp;Entry into this qualification can be by direct entry without prior meat industry skills or knowledge or after completion of a Certificate I or II in Meat Processing qualification.</p>\r\n<h4 style=\"text-align: justify;\">DELIVERY SUMMARY:</h4>\r\n<p style=\"text-align: justify;\">To achieve this qualification a total of seven &nbsp;(7) units of competency must be completed including seven (7) core and fie (5) electives. &nbsp;The program is self paced with training being in a workplace delivery environment or other flexible learning environment. &nbsp;The program has rolling enrolments which means you can start any time and do not need to wait for semesters. &nbsp;For non-traineeship enrolment the course is fee for service and the price is dependent on unit selection.</p>\r\n</div>', 'Unique College of Technology', '74.jpg', 'AMP30516 - Certificate III in Meat Processing (Slaughtering ).pdf', 1, '2021-04-26 01:16:53', '2021-06-01 05:15:41'),
(10, 1, 8, 1, 24, 'AMP30716', 'Certificate III in Meat Processing (Quality Assurance)', '<section>\r\n<div>\r\n<p style=\"text-align: justify;\">If you are an expert Butcher and looking for a qualification to boost your career at its peak, then you can keep your trust on us. We will review your skills, experience and help you to be Australian qualified. Our skills assessment process is simple, fast, and reliable with a 100% money back guarantee.</p>\r\n</div>\r\n</section>\r\n<section>\r\n<div>\r\n<h3>Description</h3>\r\n<p>This qualification covers the work activities undertaken by Quality Assurance Officers in a meat processing enterprise. Typically people undertaking this qualification will be responsible for the day-to-day monitoring, testing and application of a QA program.</p>\r\n<p>Graduates from this qualification will have a wide range of cognitive, technical and communication skills to select and apply a specialised range of tools, materials and information to:</p>\r\n<ul>\r\n<li>complete routine activities</li>\r\n<li>provide and transmit solutions to predictable and sometimes unpredictable problems</li>\r\n</ul>\r\n<p>Graduates will apply knowledge and skills to demonstrate autonomy and judgement and to take limited responsibility in known and stable contexts within established parameters.</p>\r\n<p>No occupational licensing, legislative or certification requirements are known to apply to this qualification at the time of publication.</p>\r\n</div>\r\n</section>\r\n<section>\r\n<div>\r\n<h3>Entry Requirements</h3>\r\n<p>There are no entry requirements for this qualification.</p>\r\n</div>\r\n</section>\r\n<section>\r\n<div>\r\n<h3 style=\"text-align: justify;\">Packaging Rules</h3>\r\n<p style=\"text-align: justify;\">To achieve this qualification, competency must be demonstrated in:</p>\r\n<ul>\r\n<li style=\"text-align: justify;\">17 units of competency:</li>\r\n<li style=\"text-align: justify;\">8 core units plus</li>\r\n<li style=\"text-align: justify;\">9 elective units.</li>\r\n</ul>\r\n</div>\r\n</section>', 'Unique College of Technology', '75.jpg', 'AMP30716 - Certificate III in Meat Processing (Quality Assurance).pdf', 1, '2021-04-26 01:17:52', '2021-06-01 05:18:47'),
(11, 1, 8, 1, 24, 'AMP30815', 'Certificate III in Meat Processing (Retail Butcher)', '<h2 style=\"text-align: justify;\">Qualification Description</h2>\r\n<p style=\"text-align: justify;\">This qualification is the trade qualification for butchers.</p>\r\n<p style=\"text-align: justify;\">No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>\r\n<h2 style=\"text-align: justify;\">Entry Requirements</h2>\r\n<p style=\"text-align: justify;\">There are no entry requirements for this qualification.</p>\r\n<h2 style=\"text-align: justify;\">Packaging Rules</h2>\r\n<p style=\"text-align: justify;\">To achieve this qualification, competency must be demonstrated in:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>44 units of competency:</li>\r\n</ul>\r\n<ul style=\"text-align: justify;\">\r\n<li>37 core units plus</li>\r\n<li>7 elective units.</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Elective units must ensure the integrity of the qualification&rsquo;s Australian Qualification Framework (AQF) alignment and contribute to a valid, industry-supported vocational outcome. The electives are to be chosen as follows:</p>\r\n<ul>\r\n<li style=\"text-align: justify;\">1 unit from Group A (Stage 1)</li>\r\n<li style=\"text-align: justify;\">1 unit from Group B (Stage 2)</li>\r\n<li style=\"text-align: justify;\">1 unit from Group C (Stage 3)</li>\r\n<li style=\"text-align: justify;\">4 units from Groups C or D</li>\r\n</ul>', 'Unique College of Technology', '76.jpg', 'AMP30815 - Certificate III in Meat Processing (Retail Butcher).pdf', 1, '2021-04-26 01:18:34', '2021-06-01 05:20:46'),
(12, 1, 9, 1, 24, 'AUR30316', 'Certificate III in Automotive Electrical Technology', '<h2 style=\"text-align: justify;\"><span id=\"content_0_lbloverview\">Course Overview</span></h2>\r\n<p style=\"text-align: justify;\"><span id=\"content_0_lblcoursestructure\"></span></p>\r\n<p style=\"text-align: justify;\">The Certificate III in Automotive Electrical Technology (AUR30316) course enables participants to gain skills in all aspects of the automotive electrical trade. This automotive course is the nationally recognised qualification for becoming an automotive electrician. The course covers health and safety, customer relations and using tools, repairing, servicing and testing all the elements of electrical systems.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h2 style=\"text-align: justify;\"><span id=\"content_0_lstoverview_ctrl0_lblquestion\">How will I be assessed?</span></h2>\r\n<p style=\"text-align: justify;\"><span id=\"content_0_lstoverview_ctrl0_lblanswer\"></span></p>\r\n<p style=\"text-align: justify;\">You will be assessed to show that you have achieved the skills and knowledge required by the course. Assessment may include written, oral or practical assessment methods. You will be advised in advance about the type of assessment and the how it will operate. There is the opportunity for reassessment and appeal and you will be provided with this information.</p>', 'Unique College of Technology', '78.jpg', 'AUR30316-Certificate III in Automotive Electrical Technology.pdf', 1, '2021-04-26 01:20:32', '2021-06-01 05:22:20'),
(13, 1, 9, 1, 24, 'AUR30616', 'Certificate III in Light Vehicle Mechanical Technology', '<h2>Description</h2>\r\n<p id=\"CourseDescription\" style=\"text-align: justify;\">This course examines service and repair of mechanical, electrical and electronic components and systems associated with light vehicle engines, suspension, steering, braking, transmissions, ignition and electrical accessory systems and related components. Tasks also include discussing problems with customers to detect faults through various diagnostic procedures and use of specialised diagnostic equipment. The introduction of electronic control for engine, emission and dynamic vehicle control systems has given an added dimension to the complexity of this tradition motor mechanic&rsquo;s work.</p>', NULL, '79.jpg', 'AUR30616 - Certificate III in Light Vehicle Mechanical Technology.pdf', 1, '2021-04-26 01:22:26', '2021-06-01 05:25:05');
INSERT INTO `courses` (`id`, `action_user`, `course_industries_id`, `qualification_id`, `course_categories_id`, `course_code`, `course_name`, `course_desc`, `rto`, `thumbnail`, `checklist`, `isPublished`, `created_at`, `updated_at`) VALUES
(14, 1, 10, 1, 24, 'BSB30115', 'Certificate III in Business', '<h2>Qualification Description</h2>\r\n<p>This qualification reflects the varied roles of individuals across different industry sectors who apply a broad range of competencies using some discretion, judgment and relevant theoretical knowledge. They may provide technical advice and support to a team.</p>\r\n<p>Licensing/Regulatory Information&nbsp;</p>\r\n<p>No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>Nil</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 12&nbsp;</p>\r\n<p>1 core unit&nbsp;&nbsp;plus</p>\r\n<p>11 elective units, of which:&nbsp;</p>\r\n<ul>\r\n<li>7 of the elective units must be selected from the elective units listed below</li>\r\n<li>4 elective units may be selected from the elective units listed below, from this Training Package or from any current accredited course or endorsed Training Package at the same qualification level</li>\r\n<li>if not listed below, 1 elective unit may be selected from a Certificate II qualification and 2 elective units may be taken from a Certificate IV qualification.</li>\r\n</ul>\r\n<p>Elective units must be relevant to the work environment and the qualification, maintain the integrity of the AQF alignment and contribute to a valid, industry-supported vocational outcome.</p>\r\n<h2>Core Units&nbsp;</h2>\r\n<p>BSBWHS302 Apply knowledge of WHS legislation in the workplace</p>\r\n<h2>Elective Units&nbsp;</h2>\r\n<p>BSBADM311 Maintain business resources</p>\r\n<p>BSBCMM301 Process customer complaints</p>\r\n<p>BSBCUS301 Deliver and monitor a service to customers</p>\r\n<p>BSBDIV301 Work effectively with diversity</p>\r\n<p>BSBFIA301 Maintain financial records</p>\r\n<p>BSBFLM303 Contribute to effective workplace relationships</p>\r\n<p>BSBFLM305 Support operational plan</p>\r\n<p>BSBFLM306 Provide workplace information and resourcing plans</p>\r\n<p>BSBFLM309 Support continuous improvement systems and processes</p>\r\n<p>BSBFLM311 Support a workplace learning environment</p>\r\n<p>BSBFLM312 Contribute to team effectiveness</p>\r\n<p>BSBINM301 Organise workplace information</p>\r\n<p>BSBINM302 Utilise a knowledge management system</p>\r\n<p>BSBINN301 Promote innovation in a team environment</p>\r\n<p>BSBIPR301 Comply with organisational requirements for protection and use of intellectual property</p>\r\n<p>BSBITU306 Design and produce business documents</p>\r\n<p>BSBITU309 Produce desktop published documents</p>\r\n<p>BSBITU311 Use simple relational databases</p>\r\n<p>BSBITU312 Create electronic presentations</p>\r\n<p>BSBITU313 Design and produce digital text documents</p>\r\n<p>BSBITU314 Design and produce spreadsheets</p>\r\n<p>BSBITU315 Purchase goods and services online</p>\r\n<p>BSBPRO301 Recommend products and services</p>\r\n<p>BSBPUR301 Purchase goods and services</p>\r\n<p>BSBSUS401 Implement and monitor environmentally sustainable work practices</p>\r\n<p>BSBWHS332X Apply infection prevention and control procedures to own work activities</p>\r\n<p>BSBWOR301 Organise personal work priorities and development</p>\r\n<p>BSBWOR302 Work effectively as an off-site worker</p>\r\n<p>BSBWRK311 Develop self-awareness</p>\r\n<p>BSBWRT301 Write simple documents</p>\r\n<p>BSBXCM301 Engage in workplace communication</p>\r\n<p>BSBXTW301 Work in a team</p>', 'Unique College of Technology,Bright College', '84.jpg', 'BSB30115 - Certificate III in Business.pdf', 1, '2021-04-26 01:23:50', '2021-06-01 05:40:14'),
(15, 1, 7, 1, 24, 'BSB30215', 'Certificate III in Customer Engagement', '<h2 style=\"text-align: justify;\">Qualification Description</h2>\r\n<p style=\"text-align: justify;\">This qualification reflects the role of individuals working in a range of complex customer service roles.</p>\r\n<p style=\"text-align: justify;\">Duties at this level would include working with multiple communication channels, providing excellent customer service, adhering to key performance indicators, working in a team environment, providing support to a team, providing technical advice and capturing data.</p>\r\n<p style=\"text-align: justify;\">Individuals would work under supervision, but may have some authority to delegate.</p>\r\n<h3 style=\"text-align: justify;\">Licensing/Regulatory Information&nbsp;</h3>\r\n<p style=\"text-align: justify;\">No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h2 style=\"text-align: justify;\">Entry Requirements</h2>\r\n<p style=\"text-align: justify;\">Nil</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h2 style=\"text-align: justify;\">Packaging Rules</h2>\r\n<p style=\"text-align: justify;\">Total number of units = 12&nbsp;&nbsp;</p>\r\n<p style=\"text-align: justify;\">4 core units&nbsp;&nbsp;plus</p>\r\n<p style=\"text-align: justify;\">8 elective units,&nbsp;&nbsp;of which:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>2 units must be from Group A elective units below</li>\r\n<li>6 units may be from Group A or Group B elective units, or from qualifications at the same level or one higher in any endorsed Training Package or accredited course.</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Elective units must be relevant to the work environment and the qualification, maintain the integrity of the AQF alignment and contribute to a valid, industry-supported vocational outcome.</p>\r\n<h2 style=\"text-align: justify;\">&nbsp;</h2>\r\n<h2 style=\"text-align: justify;\">Core Units&nbsp;</h2>\r\n<p style=\"text-align: justify;\">BSBCUE301 Use multiple information systems</p>\r\n<p style=\"text-align: justify;\">BSBCUE307 Work effectively in customer engagement</p>\r\n<p style=\"text-align: justify;\">BSBCUE309 Develop product and service knowledge for customer engagement operation</p>\r\n<p style=\"text-align: justify;\">BSBCUS301 Deliver and monitor a service to customers</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h2 style=\"text-align: justify;\">Elective Units&nbsp;</h2>\r\n<p style=\"text-align: justify;\">Group A&nbsp;</p>\r\n<p style=\"text-align: justify;\">BSBCUE203 Conduct customer engagement</p>\r\n<p style=\"text-align: justify;\">BSBCUE204 Collect data</p>\r\n<p style=\"text-align: justify;\">BSBCUE302 Deploy customer service field staff</p>\r\n<p style=\"text-align: justify;\">BSBCUE303 Conduct a telemarketing campaign</p>\r\n<p style=\"text-align: justify;\">BSBCUE304 Provide sales solutions to customers</p>\r\n<p style=\"text-align: justify;\">BSBCUE305 Process credit applications</p>\r\n<p style=\"text-align: justify;\">BSBCUE306 Process complex accounts</p>\r\n<p style=\"text-align: justify;\">BSBCUE308 Conduct outbound customer engagement</p>\r\n<p style=\"text-align: justify;\">BSBCUE403 Schedule customer engagement activity</p>\r\n<p style=\"text-align: justify;\">BSBCMM301 Process customer complaints</p>\r\n<p style=\"text-align: justify;\">BSBITU213 Use digital technologies to communicate remotely</p>\r\n<p style=\"text-align: justify;\">BSBITU307 Develop keyboarding speed and accuracy</p>\r\n<p style=\"text-align: justify;\">BSBLED301 Undertake e-learning</p>\r\n<p style=\"text-align: justify;\">BSBWOR203 Work effectively with others</p>\r\n<p style=\"text-align: justify;\">BSBWOR301 Organise personal work priorities and development</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Group B&nbsp;</p>\r\n<p style=\"text-align: justify;\">BSBMGT401 Show leadership in the workplace</p>\r\n<p style=\"text-align: justify;\">BSBMGT402 Implement operational plan</p>\r\n<p style=\"text-align: justify;\">BSBMGT405 Provide personal leadership</p>\r\n<p style=\"text-align: justify;\">BSBSLS407 Identify and plan sales prospects</p>\r\n<p style=\"text-align: justify;\">BSBSLS408 Present, secure and support sales solutions</p>\r\n<p style=\"text-align: justify;\">BSBSUS401 Implement and monitor environmentally sustainable work practices</p>\r\n<p style=\"text-align: justify;\">BSBWHS201 Contribute to health and safety of self and others</p>\r\n<p style=\"text-align: justify;\">BSBWHS307 Apply knowledge of WHS laws in the workplace</p>\r\n<p style=\"text-align: justify;\">BSBWOR201 Manage personal stress in the workplace</p>\r\n<p style=\"text-align: justify;\">BSBXDB301 Respond to the service needs of customers and clients with disability</p>\r\n<p style=\"text-align: justify;\">FNSSAM301 Identify opportunities for cross-selling products and services</p>\r\n<p style=\"text-align: justify;\">ICTICT209 Interact with ICT clients</p>\r\n<p style=\"text-align: justify;\">ICTSAS204 Record client support requirements</p>\r\n<p style=\"text-align: justify;\">ICTSAS305 Provide ICT advice to clients</p>', NULL, '57.jpg', 'BSB30215 - Certificate III in Customer Engagement.pdf', 1, '2021-04-26 01:25:27', '2021-06-01 05:41:51'),
(16, 1, 10, 1, 24, 'BSB30315', 'Certificate III in Micro Business Operations', '<h2 style=\"text-align: justify;\">Qualification Description</h2>\r\n<p style=\"text-align: justify;\">This qualification reflects the role of skilled independent and micro-business contractors who apply a broad range of competencies in varied contexts, using some discretion and judgement and relevant theoretical knowledge. They may provide technical advice and support to a small team.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h4 style=\"text-align: justify;\">Licensing/Regulatory Information</h4>\r\n<p style=\"text-align: justify;\">No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>\r\n<h2 style=\"text-align: justify;\">Entry Requirements</h2>\r\n<p style=\"text-align: justify;\">Nil</p>\r\n<h2 style=\"text-align: justify;\">Packaging Rules</h2>\r\n<p style=\"text-align: justify;\">Total number of units = 10&nbsp;</p>\r\n<p style=\"text-align: justify;\">5 core units&nbsp;&nbsp;plus</p>\r\n<p style=\"text-align: justify;\">5 elective units,&nbsp;&nbsp;of which:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>all 5 elective units may be selected from the elective units listed below or from any currently endorsed Training Package or accredited course at the same qualification level</li>\r\n<li>if not listed below, 1 elective unit may be selected from a Certificate II or Certificate IV qualification.</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Elective units must be relevant to the work environment and the qualification, maintain the integrity of the AQF alignment and contribute to a valid, industry-supported vocational outcome.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h4 style=\"text-align: justify;\">Core Units</h4>\r\n<p style=\"text-align: justify;\">BSBSMB301 Investigate micro business opportunities</p>\r\n<p style=\"text-align: justify;\">BSBSMB302 Develop a micro business proposal</p>\r\n<p style=\"text-align: justify;\">BSBSMB303 Organise finances for the micro business</p>\r\n<p style=\"text-align: justify;\">BSBSMB304 Determine resource requirements for the micro business</p>\r\n<p style=\"text-align: justify;\">BSBSMB305 Comply with regulatory, taxation and insurance requirements for the micro business</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h4 style=\"text-align: justify;\">Elective Units</h4>\r\n<p style=\"text-align: justify;\">BSBCRT301 Develop and extend critical and creative thinking skills</p>\r\n<p style=\"text-align: justify;\">BSBCUS301 Deliver and monitor a service to customers</p>\r\n<p style=\"text-align: justify;\">BSBEBU401 Review and maintain a website</p>\r\n<p style=\"text-align: justify;\">BSBFIA301 Maintain financial records</p>\r\n<p style=\"text-align: justify;\">BSBFIA303 Process accounts payable and receivable</p>\r\n<p style=\"text-align: justify;\">BSBHRM405 Support the recruitment, selection and induction of staff</p>\r\n<p style=\"text-align: justify;\">BSBINN301 Promote innovation in a team environment</p>\r\n<p style=\"text-align: justify;\">BSBINT303 Organise the importing and exporting of goods</p>\r\n<p style=\"text-align: justify;\">BSBIPR405 Protect and use intangible assets in small business</p>\r\n<p style=\"text-align: justify;\">BSBITU315 Purchase goods and services online</p>\r\n<p style=\"text-align: justify;\">BSBREL401 Establish networks</p>\r\n<p style=\"text-align: justify;\">BSBSMB201 Identify suitability for micro business</p>\r\n<p style=\"text-align: justify;\">BSBSMB306 Plan a home-based business</p>\r\n<p style=\"text-align: justify;\">BSBSMB307 Set up information and communications technology for the micro business</p>\r\n<p style=\"text-align: justify;\">BSBSMB308 Improve energy efficiency in micro or small business operations</p>\r\n<p style=\"text-align: justify;\">BSBSMB423 Create a digital technology plan for small business</p>\r\n<p style=\"text-align: justify;\">BSBSUS401 Implement and monitor environmentally sustainable work practices</p>\r\n<p style=\"text-align: justify;\">BSBWOR301 Organise personal work priorities and development</p>\r\n<p style=\"text-align: justify;\">BSBWOR302 Work effectively as an off-site worker</p>\r\n<p style=\"text-align: justify;\">BSBWOR424 Develop a time management plan</p>\r\n<p style=\"text-align: justify;\">BSBXCS301 Protect own personal online profile from cyber security threats</p>\r\n<p style=\"text-align: justify;\">BSBXCS302 Identify and report online security threats</p>\r\n<p style=\"text-align: justify;\">BSBXCS303 Securely manage personally identifiable information and workplace information</p>\r\n<p style=\"text-align: justify;\">FNSFLT201 Develop and use a personal budget</p>', NULL, '85.jpg', 'BSB30315 - Certificate III in Micro Business Operations.pdf', 1, '2021-04-26 01:28:02', '2021-06-01 05:42:30'),
(17, 1, 10, 1, 24, 'BSB30415', 'Certificate III in Business Administration', '<h2 style=\"text-align: justify;\">Qualification Description</h2>\r\n<p style=\"text-align: justify;\">This qualification applies to a range of administrative roles in varied contexts.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Individuals in these positions use some discretion and judgement and may provide technical advice and support to a team.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>Licensing/Regulatory Information&nbsp;</strong></p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>\r\n<h2 style=\"text-align: justify;\">Entry Requirements</h2>\r\n<p style=\"text-align: justify;\">Nil</p>\r\n<h2 style=\"text-align: justify;\">Packaging Rules</h2>\r\n<p style=\"text-align: justify;\">Total number of units = 13&nbsp;</p>\r\n<p style=\"text-align: justify;\">2 core units&nbsp;&nbsp;plus</p>\r\n<p style=\"text-align: justify;\">11 elective units&nbsp;, of which:</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>7 elective units must be selected from the Group A units listed below</li>\r\n<li>4 elective units may be selected from the Group A or Group B elective units listed below, or any currently endorsed Training Package or accredited course at the same qualification level</li>\r\n<li>if not listed below, 2 of the electives units may be selected from a Certificate II or Certificate IV qualification.</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Elective units must be relevant to the work environment and the qualification, maintain the integrity of the AQF alignment and contribute to a valid, industry-supported vocational outcome.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h2 style=\"text-align: justify;\">Core Units&nbsp;</h2>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">BSBITU307 Develop keyboarding speed and accuracy</p>\r\n<p style=\"text-align: justify;\">BSBWHS201 Contribute to health and safety of self and others</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h2 style=\"text-align: justify;\">Elective Units&nbsp;</h2>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Group A&nbsp;</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">BSBADM307 Organise schedules</p>\r\n<p style=\"text-align: justify;\">BSBFIA302 Process payroll</p>\r\n<p style=\"text-align: justify;\">BSBFIA303 Process accounts payable and receivable</p>\r\n<p style=\"text-align: justify;\">BSBFIA304 Maintain a general ledger</p>\r\n<p style=\"text-align: justify;\">BSBITU312 Create electronic presentations</p>\r\n<p style=\"text-align: justify;\">BSBITU313 Design and produce digital text documents</p>\r\n<p style=\"text-align: justify;\">BSBITU314 Design and produce spreadsheets</p>\r\n<p style=\"text-align: justify;\">BSBITU306 Design and produce business documents</p>\r\n<p style=\"text-align: justify;\">BSBITU309 Produce desktop published documents</p>\r\n<p style=\"text-align: justify;\">BSBWRT301 Write simple documents</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Group B units&nbsp;</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">BSBADM302 Produce texts from notes</p>\r\n<p style=\"text-align: justify;\">BSBADM303 Produce texts from audio transcription</p>\r\n<p style=\"text-align: justify;\">BSBADM311 Maintain business resources</p>\r\n<p style=\"text-align: justify;\">BSBCMM301 Process customer complaints</p>\r\n<p style=\"text-align: justify;\">BSBCUS301 Deliver and monitor a service to customers</p>\r\n<p style=\"text-align: justify;\">BSBDIV301 Work effectively with diversity</p>\r\n<p style=\"text-align: justify;\">BSBFIA301 Maintain financial records</p>\r\n<p style=\"text-align: justify;\">BSBINM301 Organise workplace information</p>\r\n<p style=\"text-align: justify;\">BSBINM302 Utilise a knowledge management system</p>\r\n<p style=\"text-align: justify;\">BSBINM303 Handle receipt and despatch of information</p>\r\n<p style=\"text-align: justify;\">BSBINN201 Contribute to workplace innovation</p>\r\n<p style=\"text-align: justify;\">BSBIPR301 Comply with organisational requirements for protection and use of intellectual property</p>\r\n<p style=\"text-align: justify;\">BSBITU311 Use simple relational databases</p>\r\n<p style=\"text-align: justify;\">BSBITU315 Purchase goods and services online</p>\r\n<p style=\"text-align: justify;\">BSBPRO301 Recommend products and services</p>\r\n<p style=\"text-align: justify;\">BSBSUS201 Participate in environmentally sustainable work practices</p>\r\n<p style=\"text-align: justify;\">BSBWOR204 Use business technology</p>\r\n<p style=\"text-align: justify;\">BSBWOR301 Organise personal work priorities and development</p>\r\n<p style=\"text-align: justify;\">BSBWOR302 Work effectively as an off-site worker</p>\r\n<p style=\"text-align: justify;\">BSBWHS401 Implement and monitor WHS policies, procedures and programs to meet legislative requirements</p>', NULL, '86.jpg', 'BSB30415-Certificate III in Business Administration.pdf', 1, '2021-04-26 01:28:50', '2021-06-01 05:43:32'),
(18, 1, 10, 1, 24, 'BSB30615', 'Certificate III in International Trade', '<h2 style=\"text-align: justify;\">Qualification Description</h2>\r\n<p style=\"text-align: justify;\">This qualification is suitable for skilled operators who use some discretion, judgement and relevant theoretical knowledge to a broad range of international trade competencies in varied work roles.</p>\r\n<p style=\"text-align: justify;\">Individuals in these positions may provide technical advice and support to a team.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>Licensing/Regulatory Information&nbsp;</strong></p>\r\n<p style=\"text-align: justify;\">No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h2 style=\"text-align: justify;\">Entry Requirements</h2>\r\n<p style=\"text-align: justify;\">Nil</p>\r\n<h2 style=\"text-align: justify;\">Packaging Rules</h2>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Total number of units = 12&nbsp;</p>\r\n<p style=\"text-align: justify;\">1 core unit&nbsp;&nbsp;plus</p>\r\n<p style=\"text-align: justify;\">11 elective units, of which:&nbsp;</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>5 elective units must be selected from the Group A units listed below</li>\r\n<li>4 elective units must be selected from the Group A or Group B units listed below</li>\r\n<li>2 elective units may be selected from the Group A or Group B elective units listed below, or any currently endorsed Training Package or accredited course at the same qualification level</li>\r\n<li>if not listed below, 1 of the elective units may be selected from either a Certificate II or Certificate IV qualification.</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Elective units must be relevant to the work environment and the qualification, maintain the integrity of the AQF alignment and contribute to a valid, industry-supported vocational outcome.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h2 style=\"text-align: justify;\">Core Units&nbsp;</h2>\r\n<p style=\"text-align: justify;\">BSBWHS401 Implement and monitor WHS policies, procedures and programs to meet legislative requirements</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h2 style=\"text-align: justify;\">Elective Units&nbsp;</h2>\r\n<p style=\"text-align: justify;\">Group A&nbsp;</p>\r\n<p style=\"text-align: justify;\">BSBINT301 Apply knowledge of the international trade environment to complete work</p>\r\n<p style=\"text-align: justify;\">BSBINT302 Apply knowledge of legislation relevant to international trade to complete work</p>\r\n<p style=\"text-align: justify;\">BSBINT303 Organise the importing and exporting of goods</p>\r\n<p style=\"text-align: justify;\">BSBINT304 Assist in the international transfer of services</p>\r\n<p style=\"text-align: justify;\">BSBINT305 Prepare business documents for the international trade of goods</p>\r\n<p style=\"text-align: justify;\">BSBINT306 Apply knowledge of international finance and insurance to complete work requirements</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Group B units&nbsp;</p>\r\n<p style=\"text-align: justify;\">BSBADM311 Maintain business resources</p>\r\n<p style=\"text-align: justify;\">BSBCMM301 Process customer complaints</p>\r\n<p style=\"text-align: justify;\">BSBCUS301 Deliver and monitor a service to customers</p>\r\n<p style=\"text-align: justify;\">BSBDIV301 Work effectively with diversity</p>\r\n<p style=\"text-align: justify;\">BSBFIA301 Maintain financial records</p>\r\n<p style=\"text-align: justify;\">BSBINM301 Organise workplace information</p>\r\n<p style=\"text-align: justify;\">BSBINM302 Utilise a knowledge management system</p>\r\n<p style=\"text-align: justify;\">BSBITU306 Design and produce business documents</p>\r\n<p style=\"text-align: justify;\">BSBITU313 Design and produce digital text documents</p>\r\n<p style=\"text-align: justify;\">BSBITU315 Purchase goods and services online</p>\r\n<p style=\"text-align: justify;\">BSBPRO301 Recommend products and services</p>\r\n<p style=\"text-align: justify;\">BSBPUR301 Purchase goods and services</p>\r\n<p style=\"text-align: justify;\">BSBSUS401 Implement and monitor environmentally sustainable work practices</p>\r\n<p style=\"text-align: justify;\">BSBWOR301 Organise personal work priorities and development</p>\r\n<p style=\"text-align: justify;\">BSBWOR302 Work effectively as an off-site worker</p>\r\n<p style=\"text-align: justify;\">BSBWRT301 Write simple documents</p>', NULL, '87.jpg', 'BSB30615-Certificate III in International Trade.pdf', 1, '2021-04-26 01:30:11', '2021-06-01 05:44:39'),
(19, 1, 11, 1, 24, 'BSB30715', 'Certificate III in work Health & Safety', '<h2>Qualification Description</h2>\r\n<p>This qualification is suitable for skilled operators who take on Work Health and Safety (WHS) responsibilities in addition to their main duties. They may provide technical advice and support to a team and apply a range of competencies in varied work contexts.</p>\r\n<p><strong>Licensing/Regulatory Information&nbsp;</strong></p>\r\n<p>No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>\r\n<p>&nbsp;</p>\r\n<h2>Entry Requirements</h2>\r\n<p>Nil</p>\r\n<p>&nbsp;</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 10&nbsp;</p>\r\n<p>5 core units&nbsp; plus</p>\r\n<p>5 elective units,&nbsp; of which:</p>\r\n<ul>\r\n<li>3 units must be from the elective units below</li>\r\n<li>2 units may be from any currently endorsed Training Package or accredited course at the same qualification level</li>\r\n<li>If not listed, 1 elective unit may be selected from a Certificate II or Certificate IV from any currently endorsed Training Package or accredited course.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Elective units must be relevant to the work environment and the qualification, maintain the integrity of the AQF alignment and contribute to a valid, industry-supported vocational outcome.</p>\r\n<p>&nbsp;</p>\r\n<h2>Core Units&nbsp;</h2>\r\n<p>BSBWHS302 Apply knowledge of WHS legislation in the workplace</p>\r\n<p>BSBWHS303 Participate in WHS hazard identification, risk assessment and risk control</p>\r\n<p>BSBWHS304 Participate effectively in WHS communication and consultation processes</p>\r\n<p>BSBWHS305 Contribute to WHS issue resolution</p>\r\n<p>PUAWER001B Identify, prevent and report potential workplace emergency situations</p>\r\n<p>&nbsp;</p>\r\n<h2>Elective Units&nbsp;</h2>\r\n<p>BSBCMM201 Communicate in the workplace</p>\r\n<p>BSBDIV301 Work effectively with diversity</p>\r\n<p>BSBFLM303 Contribute to effective workplace relationships</p>\r\n<p>BSBINM301 Organise workplace information</p>\r\n<p>BSBINN201 Contribute to workplace innovation</p>\r\n<p>BSBLDR402 Lead effective workplace relationships</p>\r\n<p>BSBLDR403 Lead team effectiveness</p>\r\n<p>BSBSUS401 Implement and monitor environmentally sustainable work practices</p>\r\n<p>BSBWHS406 Assist with responding to incidents</p>\r\n<p>BSBWRT301 Write simple documents</p>\r\n<p>CPPWMT3044A Identify wastes and hazards</p>\r\n<p>HLTAID003 Provide first aid</p>\r\n<p>HLTAID005 Provide first aid in remote situation</p>\r\n<p>PUAWER004B Respond to workplace emergencies</p>', NULL, '23.jpg', 'BSB30715-Certificate III in work Health _ Safety.pdf', 1, '2021-04-26 06:03:52', '2021-06-01 05:45:39'),
(20, 1, 10, 1, 24, 'BSB30915', 'Certificate III in Business Administration (Education)', '<h2 style=\"text-align: justify;\">Qualification Description</h2>\r\n<p style=\"text-align: justify;\">This qualification is suitable for individuals who may provide technical advice and support to a team using some discretion and judgement across broad range of administrative competencies in an educational or school support context.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>Licensing/Regulatory Information&nbsp;</strong></p>\r\n<p style=\"text-align: justify;\">No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h2 style=\"text-align: justify;\">Entry Requirements</h2>\r\n<p style=\"text-align: justify;\">Nil</p>\r\n<h2 style=\"text-align: justify;\">Packaging Rules</h2>\r\n<p style=\"text-align: justify;\">Total number of units = 13&nbsp;</p>\r\n<p style=\"text-align: justify;\">3 core units&nbsp;&nbsp;plus</p>\r\n<p style=\"text-align: justify;\">10 elective units, of which:&nbsp;</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>4 elective units must be selected from the Group A units listed below</li>\r\n<li>4 elective units must be selected from the Group B units listed below</li>\r\n<li>2 elective units may be selected from the Group A, Group B or Group C units listed below, or any currently endorsed Training Package or accredited course at the same qualification level or one level lower or higher.</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Elective units must be relevant to the work environment and the qualification, maintain the integrity of the AQF alignment and contribute to a valid, industry-supported vocational outcome.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h2 style=\"text-align: justify;\">Core Units&nbsp;</h2>\r\n<p style=\"text-align: justify;\">BSBITU307 Develop keyboarding speed and accuracy</p>\r\n<p style=\"text-align: justify;\">BSBWHS201 Contribute to health and safety of self and others</p>\r\n<p style=\"text-align: justify;\">BSBIND301 Work effectively in an educational environment</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h2 style=\"text-align: justify;\">Elective Units&nbsp;</h2>\r\n<p style=\"text-align: justify;\">Group A units&nbsp;</p>\r\n<p style=\"text-align: justify;\">BSBADM405 Organise meetings</p>\r\n<p style=\"text-align: justify;\">BSBADM406 Organise business travel</p>\r\n<p style=\"text-align: justify;\">BSBCUS301 Deliver and monitor a service to customers</p>\r\n<p style=\"text-align: justify;\">BSBEBU401 Review and maintain a website</p>\r\n<p style=\"text-align: justify;\">BSBMKG408 Conduct market research</p>\r\n<p style=\"text-align: justify;\">CHCCCS007 Develop and implement service programs</p>\r\n<p style=\"text-align: justify;\">ICTICT103 Use, communicate and search securely on the internet</p>\r\n<p style=\"text-align: justify;\">PSPETH001 Uphold the values and principles of public service</p>\r\n<p style=\"text-align: justify;\">PSPGEN021 Contribute to conflict management</p>\r\n<p style=\"text-align: justify;\">PSPLEG001 Comply with legislation in the public sector</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Group B units&nbsp;</p>\r\n<p style=\"text-align: justify;\">BSBADM307 Organise schedules</p>\r\n<p style=\"text-align: justify;\">BSBFIA302 Process payroll</p>\r\n<p style=\"text-align: justify;\">BSBFIA303 Process accounts payable and receivable</p>\r\n<p style=\"text-align: justify;\">BSBFIA304 Maintain a general ledger</p>\r\n<p style=\"text-align: justify;\">BSBITU306 Design and produce business documents</p>\r\n<p style=\"text-align: justify;\">BSBITU309 Produce desktop published documents</p>\r\n<p style=\"text-align: justify;\">BSBITU312 Create electronic presentations</p>\r\n<p style=\"text-align: justify;\">BSBITU313 Design and produce digital text documents</p>\r\n<p style=\"text-align: justify;\">BSBITU314 Design and produce spreadsheets</p>\r\n<p style=\"text-align: justify;\">BSBWRT301 Write simple documents</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Group C units&nbsp;</p>\r\n<p style=\"text-align: justify;\">BSBADM302 Produce texts from notes</p>\r\n<p style=\"text-align: justify;\">BSBADM303 Produce texts from audio transcription</p>\r\n<p style=\"text-align: justify;\">BSBADM311 Maintain business resources</p>\r\n<p style=\"text-align: justify;\">BSBCMM301 Process customer complaints</p>\r\n<p style=\"text-align: justify;\">BSBDIV301 Work effectively with diversity</p>\r\n<p style=\"text-align: justify;\">BSBFIA301 Maintain financial records</p>\r\n<p style=\"text-align: justify;\">BSBINM301 Organise workplace information</p>\r\n<p style=\"text-align: justify;\">BSBINM302 Utilise a knowledge management system</p>\r\n<p style=\"text-align: justify;\">BSBINM303 Handle receipt and despatch of information</p>\r\n<p style=\"text-align: justify;\">BSBINN201 Contribute to workplace innovation</p>\r\n<p style=\"text-align: justify;\">BSBITU311 Use simple relational databases</p>\r\n<p style=\"text-align: justify;\">BSBITU315 Purchase goods and services online</p>\r\n<p style=\"text-align: justify;\">BSBPRO301 Recommend products and services</p>\r\n<p style=\"text-align: justify;\">BSBSUS201 Participate in environmentally sustainable work practices</p>\r\n<p style=\"text-align: justify;\">BSBWHS401 Implement and monitor WHS policies, procedures and programs to meet legislative requirements</p>\r\n<p style=\"text-align: justify;\">BSBWOR204 Use business technology</p>\r\n<p style=\"text-align: justify;\">BSBWOR301 Organise personal work priorities and development</p>\r\n<p style=\"text-align: justify;\">BSBWOR302 Work effectively as an off-site worker</p>', NULL, '88.jpg', 'BSB30915-Certificate III in Business Administration (Education).pdf', 1, '2021-04-26 06:04:47', '2021-06-01 05:47:01'),
(21, 1, 10, 1, 24, 'BSB31015', 'Certificate III in Business Administration (Legal)', '<div id=\"lipsum\">\r\n<p style=\"text-align: justify;\">Lorem ipsum dolor sit amet, consectetur adipiscing elit. Phasellus cursus leo magna, id finibus dui malesuada ac. Mauris tempor porta condimentum. Nulla vel elit blandit, accumsan ipsum a, ornare nisi. Nam placerat tortor eget vulputate fermentum. Aenean turpis ante, congue eget augue at, congue rutrum arcu. Donec elementum erat sed arcu lobortis, quis laoreet nibh vestibulum. Mauris lobortis rutrum cursus. In fringilla gravida sagittis. Curabitur a massa quis nibh vehicula dapibus eu eget metus. Nam at ipsum justo.</p>\r\n<p style=\"text-align: justify;\">Vestibulum blandit mauris eu sapien consectetur, non hendrerit libero interdum. Vivamus malesuada ac nisi vitae ultricies. In fringilla varius blandit. Aenean tincidunt odio ex, eget semper ligula sodales fringilla. Mauris sit amet mollis lorem. Ut bibendum eros eu viverra interdum. Aenean non ligula a ante placerat pellentesque. Aenean feugiat sapien sit amet ullamcorper bibendum. In tellus tortor, eleifend eu finibus sit amet, dictum a tellus. Morbi feugiat in augue eu varius. Nulla semper erat at elementum aliquam. Curabitur sed elit sed nulla laoreet pellentesque. Donec non blandit nulla.</p>\r\n<p style=\"text-align: justify;\">Vivamus laoreet convallis ipsum, nec euismod nulla egestas sit amet. Quisque felis lorem, cursus in ultricies at, tristique a neque. Aenean tempor purus non lectus porttitor consectetur. Donec sed cursus turpis, vitae consectetur arcu. Maecenas venenatis lectus id erat elementum scelerisque. Maecenas arcu arcu, venenatis eget condimentum suscipit, fringilla non ante. Vestibulum sed purus maximus, varius urna ut, bibendum dui.</p>\r\n</div>', NULL, '89.jpg', 'BSB31015-Certificate III in Business Administration (Legal).pdf', 1, '2021-04-26 06:05:54', '2021-04-26 06:05:54'),
(22, 1, 10, 1, 24, 'BSB31115', 'Certificate III in Business Administration (Medical)', '<h2>Qualification Description</h2>\r\n<p>This qualification is suitable for those working in various medical administration contexts. Individuals may exercise discretion and judgement using appropriate knowledge to provide technical advice and support to a team.</p>\r\n<p>&nbsp;</p>\r\n<p>Licensing/Regulatory Information&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>\r\n<h2>Entry Requirements</h2>\r\n<p>Nil</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 13&nbsp;</p>\r\n<p>2 core units&nbsp;&nbsp;plus</p>\r\n<p>11 elective units&nbsp;, of which:</p>\r\n<p>&nbsp;</p>\r\n<ul>\r\n<li>5 elective units must be selected from the Group A units listed below</li>\r\n<li>4 elective units must be selected from the Group B units listed below</li>\r\n<li>2 elective units may be selected from Group A, Group B or Group C units listed below, or any currently endorsed Training Package or accredited course at the same qualification level or one level higher or lower.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Elective units must be relevant to the work environment and the qualification, maintain the integrity of the AQF alignment and contribute to a valid, industry-supported vocational outcome.</p>\r\n<p>&nbsp;</p>\r\n<h2>Core Units&nbsp;</h2>\r\n<p>&nbsp;</p>\r\n<p>BSBITU307 Develop keyboarding speed and accuracy</p>\r\n<p>BSBWHS201 Contribute to health and safety of self and others</p>\r\n<p>&nbsp;</p>\r\n<h2>Elective Units&nbsp;</h2>\r\n<p>&nbsp;</p>\r\n<p>Group A units&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>BSBMED301 Interpret and apply medical terminology appropriately</p>\r\n<p>BSBMED302 Prepare and process medical accounts</p>\r\n<p>BSBMED303 Maintain patient records</p>\r\n<p>BSBMED304 Assist in controlling stocks and supplies</p>\r\n<p>BSBMED305 Apply the principles of confidentiality, privacy and security within the medical environment</p>\r\n<p>BSBMED401 Manage patient record keeping system</p>\r\n<p>&nbsp;</p>\r\n<p>Group B units&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>BSBADM307 Organise schedules</p>\r\n<p>BSBFIA302 Process payroll</p>\r\n<p>BSBFIA303 Process accounts payable and receivable</p>\r\n<p>BSBFIA304 Maintain a general ledger</p>\r\n<p>BSBITU306 Design and produce business documents</p>\r\n<p>BSBITU309 Produce desktop published documents</p>\r\n<p>BSBITU312 Create electronic presentations</p>\r\n<p>BSBITU313 Design and produce digital text documents</p>\r\n<p>BSBITU314 Design and produce spreadsheets</p>\r\n<p>BSBWRT301 Write simple documents</p>\r\n<p>&nbsp;</p>\r\n<p>Group C units&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>BSBADM302 Produce texts from notes</p>\r\n<p>BSBADM303 Produce texts from audio transcription</p>\r\n<p>BSBADM311 Maintain business resources</p>\r\n<p>BSBCMM301 Process customer complaints</p>\r\n<p>BSBCUS301 Deliver and monitor a service to customers</p>\r\n<p>BSBDIV301 Work effectively with diversity</p>\r\n<p>BSBFIA301 Maintain financial records</p>\r\n<p>BSBINM301 Organise workplace information</p>\r\n<p>BSBINM302 Utilise a knowledge management system</p>\r\n<p>BSBINM303 Handle receipt and despatch of information</p>\r\n<p>BSBINN201 Contribute to workplace innovation</p>\r\n<p>BSBITU311 Use simple relational databases</p>\r\n<p>BSBITU315 Purchase goods and services online</p>\r\n<p>BSBPRO301 Recommend products and services</p>\r\n<p>BSBSUS201 Participate in environmentally sustainable work practices</p>\r\n<p>BSBWHS401 Implement and monitor WHS policies, procedures and programs to meet legislative requirements</p>\r\n<p>BSBWOR204 Use business technology</p>\r\n<p>BSBWOR301 Organise personal work priorities and development</p>\r\n<p>BSBWOR302 Work effectively as an off-site worker</p>', NULL, '90.jpg', 'BSB31115-Certificate III in Business Administration (Medical).pdf', 1, '2021-04-26 06:06:43', '2021-06-01 05:57:08'),
(23, 1, 12, 1, 24, 'CHC30113', 'Certificate III in Early Childhood Education and Care', '<h2>Qualification Description</h2>\r\n<p>This qualification reflects the role of workers in a range of early childhood education settings who work within the requirements of the Education and Care Services National Regulations and the National Quality Standard. They support the implementation of an approved learning framework, and support children&rsquo;s wellbeing, learning and development. Depending on the setting, educators may work under direct supervision or autonomously.</p>\r\n<p>&nbsp;</p>\r\n<p>Under the Education and Care Services National Law (2011) the Australian Children&rsquo;s Education and Care Quality Authority (ACECQA) publishes lists of approved early childhood education and care qualifications and information regarding regulatory requirements here:&nbsp;www.acecqa.gov.au</p>\r\n<p>&nbsp;</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 18</p>\r\n<ul>\r\n<li>15 core units</li>\r\n<li>3 elective units</li>\r\n</ul>\r\n<ul>\r\n<li>at least 1 must be selected from the electives listed below</li>\r\n<li>up to 2 units may be selected from any endorsed Training Packages or accredited courses &ndash; these units must be relevant to the work outcome.</li>\r\n</ul>\r\n<p>All electives chosen must contribute to a valid, industry-supported vocational outcome.</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Core&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCDIV002</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Promote Aboriginal and/or Torres Strait Islander cultural safety</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE001</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Develop cultural competence</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE002</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Ensure the health and safety of children</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE003</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Provide care for children</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE004</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Promote and provide healthy food and drinks</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE005</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Provide care for babies and toddlers</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE007</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Develop positive and respectful relationships with children</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE009</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Use an approved learning framework to guide practice</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE010</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Support the holistic development of children in early childhood</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE011</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Provide experiences to support children&rsquo;s play and learning</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE013</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Use information about children to inform practice</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCLEG001</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Work legally and ethically</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCPRT001</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Identify and respond to children and young people at risk</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>HLTAID004</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Provide an emergency first aid response in an education and care setting</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>HLTWHS001</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Participate in workplace health and safety</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>Electives&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCDIV001</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Work with diverse people</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE006</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Support behaviour of children and young people</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE012</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Support children to connect with their world</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE014</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Comply with family day care administration requirements</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE015</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Attend to daily functions in home based child care</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCECE017</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Foster the holistic development and wellbeing of the child in early childhood</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCPRT003</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Work collaboratively to maintain an environment safe for children and young people</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>CHCSAC004</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Support the holistic development of children in school aged care</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>BSBINN301</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Promote innovation in a team environment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>BSBSUS301</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Implement and monitor environmentally sustainable work practices</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>BSBWOR301</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Organise personal work priorities and development</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"186\">\r\n<p>SRCCRO008B</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Interact positively with infants, toddlers and parents in a recreation environment</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', NULL, '31.jpg', 'CHC30113-Certificate III in Early Childhood Education and Care.pdf', 1, '2021-04-26 06:08:07', '2021-06-02 02:56:37');
INSERT INTO `courses` (`id`, `action_user`, `course_industries_id`, `qualification_id`, `course_categories_id`, `course_code`, `course_name`, `course_desc`, `rto`, `thumbnail`, `checklist`, `isPublished`, `created_at`, `updated_at`) VALUES
(24, 1, 12, 1, 24, 'CHC30213', 'Certificate III in Education Support', '<div id=\"lipsum\">\r\n<h2>Qualification Description</h2>\r\n<p>This qualification reflects the role of workers in a range of education settings, including public and independent schools and community education settings, who provide assistance and support to teachers and students under broad-based supervision.</p>\r\n<p>&nbsp;</p>\r\n<p>No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>\r\n<p>&nbsp;</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 17</p>\r\n<ul>\r\n<li>12 core units</li>\r\n<li>5 elective units, of which:</li>\r\n</ul>\r\n<ul>\r\n<li>at least 3 must be selected from the elective units listed below</li>\r\n<li>up to 2 units may be selected from any endorsed Training Packages or accredited courses relevant to the work outcome.</li>\r\n</ul>\r\n<p>All electives chosen must contribute to a valid, industry-supported vocational outcome.</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Core&nbsp;</p>\r\n<table width=\"934\">\r\n<tbody>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCDIV001</p>\r\n</td>\r\n<td width=\"763\">\r\n<p>Work with diverse people</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCDIV002</p>\r\n</td>\r\n<td width=\"763\">\r\n<p>Promote Aboriginal and/or Torres Strait Islander cultural safety</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCECE006</p>\r\n</td>\r\n<td width=\"763\">\r\n<p>Support behaviour of children and young people</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS001</p>\r\n</td>\r\n<td width=\"763\">\r\n<p>Comply with legislative, policy and industrial requirements in the education environment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS002</p>\r\n</td>\r\n<td width=\"763\">\r\n<p>Assist implementation of planned educational programs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS003</p>\r\n</td>\r\n<td width=\"763\">\r\n<p>Contribute to student education in all developmental domains</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS004</p>\r\n</td>\r\n<td width=\"763\">\r\n<p>Contribute to organisation and management of classroom or centre</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS005</p>\r\n</td>\r\n<td width=\"763\">\r\n<p>Support the development of literacy and oral language skills</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS006</p>\r\n</td>\r\n<td width=\"763\">\r\n<p>Support the development of numeracy skills</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS007</p>\r\n</td>\r\n<td width=\"763\">\r\n<p>Work effectively with students and colleagues</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS017</p>\r\n</td>\r\n<td width=\"763\">\r\n<p>Contribute to the health and safety of students</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS018</p>\r\n</td>\r\n<td width=\"763\">\r\n<p>Support students with additional needs in the classroom environment</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>Electives&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCDIS007</p>\r\n</td>\r\n<td width=\"794\">\r\n<p>Facilitate the empowerment of people with disability</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCECE003</p>\r\n</td>\r\n<td width=\"794\">\r\n<p>Provide care for children</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCECE026</p>\r\n</td>\r\n<td width=\"794\">\r\n<p>Work in partnership with families to provide appropriate care for children</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS008</p>\r\n</td>\r\n<td width=\"794\">\r\n<p>Comply with school administrative requirements</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS009</p>\r\n</td>\r\n<td width=\"794\">\r\n<p>Communicate with parents, students and colleagues in Aboriginal or Torres Strait Islander language</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS010</p>\r\n</td>\r\n<td width=\"794\">\r\n<p>Work effectively as an Aboriginal or Torres Strait Islander education worker</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS011</p>\r\n</td>\r\n<td width=\"794\">\r\n<p>Search and assess online information</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS012</p>\r\n</td>\r\n<td width=\"794\">\r\n<p>Set up and sustain individual and small group learning areas</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS013</p>\r\n</td>\r\n<td width=\"794\">\r\n<p>Use an e-learning management system</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS014</p>\r\n</td>\r\n<td width=\"794\">\r\n<p>Support students with English as a second language</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS015</p>\r\n</td>\r\n<td width=\"794\">\r\n<p>Support development of student research skills</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS016</p>\r\n</td>\r\n<td width=\"794\">\r\n<p>Support learning for students with disabilities in a classroom environment</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS024</p>\r\n</td>\r\n<td width=\"794\">\r\n<p>Use educational strategies to support Aboriginal and/or Torres Strait Islander education</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCEDS025</p>\r\n</td>\r\n<td width=\"794\">\r\n<p>Facilitate learning for students with disabilities</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>CHCPRT001</p>\r\n</td>\r\n<td width=\"794\">\r\n<p>Identify and respond to children and young people at risk</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>HLTAID003</p>\r\n</td>\r\n<td width=\"794\">\r\n<p>Provide first aid</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"171\">\r\n<p>HLTWHS001</p>\r\n</td>\r\n<td width=\"794\">\r\n<p>Participate in workplace health and safety</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>', NULL, '32.jpg', 'CHC30213-Certificate III in Education Support.pdf', 1, '2021-04-26 06:08:44', '2021-06-02 02:57:14'),
(25, 1, 7, 1, 24, 'CHC32015', 'Certificate III in Community Services', '<h2>Qualification Description</h2>\r\n<p>This qualification reflects the role of entry level community services workers who support individuals through the provision of person-centred services. Work may include day-to-day support of individuals in community settings or support the implementation of specific community-based programs.</p>\r\n<p>&nbsp;</p>\r\n<p>At this level, work takes place under the direction of others and supervision may be direct or indirect. Work may take place in a range of community services organisations.</p>\r\n<p>&nbsp;</p>\r\n<p>No licensing, legislative, regulatory or certification requirements apply to this qualification at the time of publication.</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 12</p>\r\n<ul>\r\n<li>5 core units</li>\r\n<li>7 elective units, consisting of:</li>\r\n</ul>\r\n<ul>\r\n<li>at least 5 units from the electives listed below</li>\r\n<li>up to 2 units from the electives listed below, any endorsed Training Packages or accredited courses &ndash; these units must be relevant to the work outcome</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>All electives chosen must contribute to a valid, industry-supported vocational outcome.</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Core units&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCCCS016</p>\r\n</td>\r\n<td width=\"732\">\r\n<p>Respond to client needs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCCOM005</p>\r\n</td>\r\n<td width=\"732\">\r\n<p>Communicate and work in health or community services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCDIV001</p>\r\n</td>\r\n<td width=\"732\">\r\n<p>Work with diverse people</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>HLTWHS002</p>\r\n</td>\r\n<td width=\"732\">\r\n<p>Follow safe work practices for direct client care</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>HLTWHS006</p>\r\n</td>\r\n<td width=\"732\">\r\n<p>Manage personal stressors in the work environment</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>Elective units&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCADV001</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Facilitate the interests and rights of clients</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCAGE001</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Facilitate the empowerment of older people</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCAOD001</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Work in an alcohol and drugs context</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCAOD002</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Work with clients who are intoxicated</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCAOD003</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Provide needle and syringe services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCCCS005</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Conduct individual assessments</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCCCS009</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Facilitate responsible behaviour</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCCCS015</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Provide individualised support</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCCCS017</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Provide loss and grief support</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCCCS019</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Recognise and respond to crisis situations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCCCS023</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Support independence and wellbeing</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCCCS028</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Provide client-centred support to people in crisis</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCCDE001</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Support participative planning processes</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCCDE003</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Work within a community development framework</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCCDE004</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Implement participation and engagement strategies</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCCOM001</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Provide first point of contact</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCDFV001</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Recognise and respond appropriately to domestic and family violence</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCDIS007</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Facilitate the empowerment of people with disability</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCDIV002</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Promote Aboriginal and/or Torres Strait Islander cultural safety</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCEDU003</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Provide sexual and reproductive health information to clients</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCEDU005</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Work with clients to identify financial literacy education needs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCEDU009</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Provide parenting, health and well-being education</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCGRP001</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Support group activities</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCMHS001</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Work with people with mental health issues</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCPOL001</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Contribute to the review and development of policies</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCPRP001</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Develop and maintain networks and collaborative partnerships</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCPRT001</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Identify and respond to children and young people at risk</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCSET001</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Work with forced migrants</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCSET002</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Undertake bicultural work with forced migrants in Australia</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCSOH001</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Work with people experiencing or at risk of homelessness</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCVOL001</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Be an effective volunteer</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCYTH001</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Engage respectfully with young people</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CHCYTH003</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Support young people to create opportunities in their lives</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>HLTAID003</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Provide first aid</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>HLTAID005</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Provide first aid in remote situations</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>BSBINM301</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Organise workplace information</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>BSBWOR301</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Organise personal work priorities and development</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>CUECOR01C</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Manage own work and learning</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"221\">\r\n<p>TAEDEL301A</p>\r\n</td>\r\n<td width=\"728\">\r\n<p>Provide work skill instruction</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', NULL, '58.jpg', 'CHC32015-Certificate III in Community Services.pdf', 1, '2021-04-26 06:11:00', '2021-06-02 02:57:45'),
(26, 1, 7, 1, 24, 'CHC33015', 'Certificate III in Individual Support', '<div id=\"lipsum\">\r\n<h2>Qualification Description</h2>\r\n<p>This qualification reflects the role of workers in the community and/or residential setting who follow an individualised plan to provide person-centred support to people who may require support due to ageing, disability or some other reason. Work involves using discretion and judgement in relation to individual support as well as taking responsibility for own outputs. Workers have a range of factual, technical and procedural knowledge, as well as some theoretical knowledge of the concepts and practices required to provide person-centred support.</p>\r\n<p>&nbsp;</p>\r\n<p>To achieve this qualification, the candidate must have completed at least 120 hours of work as detailed in the Assessment Requirements of the units of competency.</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>No licensing, legislative, regulatory or certification requirements apply to this qualification at the time of publication.</p>\r\n<h2>Packaging Rules</h2>\r\n<p>Total number of units = 13</p>\r\n<ul>\r\n<li>7 core units</li>\r\n<li>6 elective units, consisting of:</li>\r\n</ul>\r\n<ul>\r\n<li>at least 4 units from the electives listed below, at least 2 units must be from those units listed under Groups A, B or C</li>\r\n<li>up to 2 units from the electives listed below, any endorsed Training Package or accredited course &ndash; these units must be relevant to the work outcome</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Any combination of electives that meets the rules above can be selected for the award of the&nbsp;Certificate III in Individual Support.&nbsp;Where appropriate, electives may be packaged to provide a qualification with a specialisation.</p>\r\n<p>&nbsp;</p>\r\n<p>Packaging for each specialisation:&nbsp;</p>\r\n<p>All Group A electives must be selected for award of the&nbsp;Certificate III in Individual Support&nbsp;(Ageing)&nbsp;and all remaining electives must be selected from Group D.</p>\r\n<p>&nbsp;</p>\r\n<p>All Group B electives must be selected for award of the&nbsp;Certificate III in Individual Support (Disability).</p>\r\n<p>&nbsp;</p>\r\n<p>At least four units from Group C electives must be selected for award of the&nbsp;Certificate III in Individual Support (Home and Community).</p>\r\n<p>&nbsp;</p>\r\n<p>Where two specialisations are completed award of the qualification would read&nbsp;Certificate III in Individual Support (Ageing, Home and Community).</p>\r\n<p>&nbsp;</p>\r\n<p>All electives chosen must contribute to a valid, industry-supported vocational outcome.</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Core units&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCCCS015</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Provide individualised support</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCCCS023</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Support independence and well being</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCCOM005</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Communicate and work in health or community services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCDIV001</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Work with diverse people</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCLEG001</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Work legally and ethically</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>HLTAAP001</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Recognise healthy body systems</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>HLTWHS002</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Follow safe work practices for direct client care</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>Elective units&nbsp;&nbsp;</p>\r\n<p>Group A electives &ndash; AGEING specialisation (4 units)&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCAGE001</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Facilitate the empowerment of older people</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCAGE005</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Provide support to people living with dementia</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCCCS011</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Meet personal support needs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>HLTINF001</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Comply with infection prevention and control policies and procedures</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Group B electives &ndash; DISABILITY specialisation (5 units)&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCDIS001</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Contribute to ongoing skills development using a strengths-based approach</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCDIS002</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Follow established person-centred behaviour supports</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCDIS003</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Support community participation and social inclusion</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCDIS007</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Facilitate the empowerment of people with disability</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>HLTINF001</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Comply with infection prevention and control policies and procedures</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Group C electives &ndash; HOME AND COMMUNITY specialisation (4 units)&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCAGE001</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Facilitate the empowerment of older people</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>OR</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCDIS007</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Facilitate the empowerment of people with disability</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"943\">\r\n<p>Plus all of the following units:</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCCCS011</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Meet personal support needs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCCCS025</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Support relationships with carers and families</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCHCS001</p>\r\n</td>\r\n<td width=\"778\">\r\n<p>Provide home and community support services</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Group D AGED CARE&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCAGE002</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Implement falls prevention strategies</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCCCS001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Address the needs of people with chronic disease</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCCCS013</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide basic foot care</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCCCS017</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide loss and grief support</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCCCS021</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Respond to suspected abuse</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCCCS025</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Support relationships with carers and families</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCCCS026</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Transport individuals</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCDIS001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Contribute to ongoing skills development using a strengths-based approach</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCDIS002</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Follow established person-centred behaviour supports</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCDIS003</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Support community participation and social inclusion</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCDIS004</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Communicate using augmentative and alternative communication strategies</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCDIS007</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Facilitate the empowerment of people with disability</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCDIV002</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Promote Aboriginal and/or Torres Strait Islander cultural safety</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCGRP001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Support group activities</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCHCS001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide home and community support services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCLAH003</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Participate in planning, implementation and monitoring of individual leisure and health programs</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCMHS001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Work with people with mental health issues</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCPAL001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Deliver care services using a palliative approach</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>HLTAHA001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Assist with an allied health program</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>HLTAHA019</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Assist with the monitoring and modification of meals and menus according to individualised plans</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>HLTAID003</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide first aid</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>HLTHPS006</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Assist clients with medication</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>HLTINF001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Comply with infection prevention and control policies and procedures</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>HLTOHC003</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Apply and manage use of basic oral health products</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>HLTOHC004</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide or assist with oral hygiene</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Other electives&nbsp;&nbsp;</p>\r\n<table width=\"943\">\r\n<tbody>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCADV001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Facilitate the interests and rights of clients</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCAGE002</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Implement falls prevention strategies</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCAGE006</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide food services</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCAOD001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Work in an alcohol and other drugs context</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCCCS001</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Address the needs of people with chronic disease</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCCCS006</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Facilitate individual service planning and delivery</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCCCS009</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Facilitate responsible behaviour</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\">\r\n<p>CHCCCS013</p>\r\n</td>\r\n<td width=\"773\">\r\n<p>Provide basic foot care</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"233\